#!/usr/bin/env bash
# Generate 7z test fixtures under testdata/7z/ using p7zip 17.06 (7za).
#
# p7zip embeds file mtimes in the archive, so source files are `touch`ed to a
# fixed epoch before archiving to keep non-encrypted fixtures byte-stable.
# Encrypted fixtures (AES-256) embed a random salt and are NOT byte-stable.
set -euo pipefail

TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
OUTDIR="$SCRIPT_DIR/../7z"
mkdir -p "$OUTDIR"
OUT="$(cd "$OUTDIR" && pwd)"
cd "$OUT"
rm -f ./*.7z

# p7zip binary (nixpkgs p7zip 17.06; supports LZMA2, ZSTD and 7zAES).
SEVENZA="${SEVENZA:-7za}"

mkdir -p "$TMP/build/dir"
printf 'Hello, hajizip!\n' > "$TMP/build/a.txt"
printf 'nested content\n' > "$TMP/build/dir/b.txt"
# Deterministic mtimes: fixed epoch for all inputs.
find "$TMP/build" -exec touch -d @0 {} +

# --- basic.7z: default LZMA2 -------------------------------------------------
(cd "$TMP/build" && "$SEVENZA" a -bd -y "$OUT/basic.7z" a.txt dir >/dev/null)

# --- nonsolid.7z: one block per file -----------------------------------------
(cd "$TMP/build" && "$SEVENZA" a -bd -y -ms=off "$OUT/nonsolid.7z" a.txt dir >/dev/null)

# --- zstd.7z: ZSTD compression method (7-Zip ZS codec id 0x4F71101) ----------
(cd "$TMP/build" && "$SEVENZA" a -bd -y -m0=zstd "$OUT/zstd.7z" a.txt dir >/dev/null)

# --- enc.7z: AES-256 + encrypted header (random salt; not byte-stable) -------
(cd "$TMP/build" && "$SEVENZA" a -bd -y -psecret -mhe=on "$OUT/enc.7z" a.txt dir >/dev/null)

# --- enc-content.7z: AES-256, plain header (random salt; not byte-stable) ----
(cd "$TMP/build" && "$SEVENZA" a -bd -y -psecret "$OUT/enc-content.7z" a.txt dir >/dev/null)

# --- nested.7z: contains zip, 7z, tar.gz and tar.xz ---------------------------
mkdir -p "$TMP/n"
cp "$SCRIPT_DIR/../zip/basic.zip" "$TMP/n/inner.zip"
cp "$OUT/basic.7z" "$TMP/n/inner.7z"
cp "$SCRIPT_DIR/../tar/basic.tar.gz" "$TMP/n/inner.tar.gz"
cp "$SCRIPT_DIR/../tar/basic.tar.xz" "$TMP/n/inner.tar.xz"
touch -d @0 "$TMP/n/"*
(cd "$TMP/n" && "$SEVENZA" a -bd -y -ms=off "$OUT/nested.7z" inner.zip inner.7z inner.tar.gz inner.tar.xz >/dev/null)

# --- corrupt.7z: truncated header (first 24 bytes only) -----------------------
head -c 24 "$OUT/basic.7z" > "$OUT/corrupt.7z"

# --- manifest -----------------------------------------------------------------
cat > manifest.toml <<'EOF'
# 7z fixtures. Generated by testdata/gen/gen-7z.sh (p7zip 17.06).
# Entries per fixture (7za l -slt output):
#   basic.7z / nonsolid.7z / zstd.7z / enc.7z / enc-content.7z:
#     a.txt (15 B), dir (dir), dir/b.txt (15 B)

[basic.7z]
name = ["a.txt", "dir", "dir/b.txt"]
method = "LZMA2"
note = "default solid LZMA2 archive"

[nonsolid.7z]
name = ["a.txt", "dir", "dir/b.txt"]
method = "LZMA2"
note = "-ms=off: one block per file (random access)"

[zstd.7z]
name = ["a.txt", "dir", "dir/b.txt"]
method = "ZSTD"
note = "-m0=zstd: ZSTD compression method (7-Zip ZS codec 0x4F71101)"

[enc.7z]
name = ["a.txt", "dir", "dir/b.txt"]
method = "LZMA2 + AES256"
password = "secret"
note = "-mhe=on: encrypted header + AES-256 content; random salt, not byte-stable"

[enc-content.7z]
name = ["a.txt", "dir", "dir/b.txt"]
method = "LZMA2 + AES256"
password = "secret"
note = "plain header, AES-256 content; random salt, not byte-stable"

[nested.7z]
name = ["inner.zip", "inner.7z", "inner.tar.gz", "inner.tar.xz"]
note = "nested archives of each supported kind; -ms=off so entries are sniffed at open"

[corrupt.7z]
name = []
note = "truncated header (first 24 bytes)"
EOF

echo "generated:"
ls -l ./*.7z
